        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: 'Inter', sans-serif;
            background-color: #ffffff;
            color: #333333;
            line-height: 1.8;
        }

        /* --- Left Side Line Navigation --- */
        .side-nav {
            position: fixed;
            left: 6vw;
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            z-index: 100;
        }

        .nav-line {
            display: flex;
            align-items: center;
            width: 40px; /* Massive hit area for easy clicking */
            height: 24px; /* Massive hit area for easy clicking */
            cursor: pointer;
            text-decoration: none;
            position: relative;
        }

        /* The actual visible line */
        .nav-line::before {
            content: '';
            display: block;
            width: 8px; /* Small inactive visual */
            height: 2px;
            background-color: #e0e0e0;
            border-radius: 2px;
            transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
        }

        /* Hover effect */
        .nav-line:hover::before {
            width: 14px;
            background-color: #999;
        }

        /* Active State (The section currently in view) */
        .nav-line.active::before {
            width: 22px; /* Active line size */
            background-color: #111;
        }

        /* Optional: Tooltip on hover */
        .nav-line::after {
            content: attr(data-title);
            position: absolute;
            left: 36px;
            top: 50%;
            transform: translateY(-50%) translateX(-10px);
            opacity: 0;
            pointer-events: none;
            font-size: 12px;
            font-weight: 500;
            color: #555;
            white-space: nowrap;
            transition: all 0.3s ease;
        }

        .nav-line:hover::after {
            opacity: 1;
            transform: translateY(-50%) translateX(0);
        }

        /* --- Blog Content Layout --- */
        .blog-container {
            max-width: 720px;
            margin: 0 auto;
            padding: 80px 20px 120px 20px;
        }

        /* Blog Header */
        .blog-header {
            margin-bottom: 60px;
        }

        .blog-header img {
            width: 100%;
            height: 400px;
            object-fit: cover;
            border-radius: 12px;
            margin-bottom: 24px;
        }

        .blog-header .caption {
            font-size: 13px;
            color: #888;
            text-align: center;
            margin-bottom: 40px;
        }

        /* Sections */
        .blog-section {
            padding: 60px 0;
            /* Minimum height to ensure scrolling is required to see the effect */
            min-height: 70vh; 
            scroll-margin-top: 100px; /* Ensures clicking link doesn't stick heading to absolute top */
        }

        .blog-section h2 {
            font-size: 22px;
            font-weight: 700;
            margin-bottom: 20px;
            color: #111;
            letter-spacing: -0.5px;
        }

        .blog-section p {
            font-size: 15px;
            color: #333;
            margin-bottom: 22px;
            line-height: 1.85;
            letter-spacing: -0.2px;
            text-align: justify; /* Gives it that blocky blog feel */
