type AuroraProps = {
  /** Three hex colors, used from the back layer to the front. */
  colors?: [string, string, string];
  /** Drift speed multiplier. */
  speed?: number;
  /** Blur radius of the back layer, in pixels. The front layer uses a little less. */
  blur?: number;
